//! Copies the update sequence generated by Nix into `OUT_DIR`.
//!
//! The sequence lives in `assets/updates.nix` and is generated by
//! `nix/scripts/gen-updates.py`. This build script does NOT generate it — it
//! only locates the finished file. Generating here would be reimplementing Nix
//! logic (invariant 5) and would leave the source of truth.
//!
//! # Why the brain reads a table it does not own
//!
//! Because it wrote one, and the two disagreed. This crate carried three steps
//! of its own — `update-inputs`, `build`, `collect-garbage` — while the table
//! the UNIT runs declares twelve with entirely different ids. Not a subset:
//! disjoint. Every step name on screen was one the sequence does not use, and
//! the "it stopped at" row, which takes its id from the report the unit writes,
//! would have drawn a bracketed key.
//!
//! The same shape as `ronoctua-notify`'s build script, down to the reason the
//! destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    let out = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    bring("RONOCTUA_UPDATES_RS", "updates.rs", &out, UPDATES);
    // AND THE CACHE POLICY, for the sweep's cadence and window. Same shape and
    // same reason: `assets/cache.nix` is the one place the numbers live, and
    // the file manager reads two of the same four.
    bring("RONOCTUA_CACHE_RS", "cache.rs", &out, CACHE);
}

/// The message a missing variable gets, per table.
const UPDATES: &str = "The update sequence is generated by Nix out of assets/updates.nix.";
const CACHE: &str = "The cache policy is generated by Nix out of assets/cache.nix.";

/// Copy one generated table into `OUT_DIR`.
fn bring(variable: &str, name: &str, out: &std::path::Path, what: &str) {
    println!("cargo:rerun-if-env-changed={variable}");

    let generated = env::var(variable).unwrap_or_else(|_| {
        panic!(
            "{variable} is not set.\n\
             \n\
             {what}\n\
             Enter the environment with `direnv allow` (or `nix develop`), which\n\
             sets the variable, or build through the flake with `nix build`.\n\
             \n\
             Generating it here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = out.join(name);
    // DELETE FIRST. The file comes from the store, and `fs::copy` inherits the
    // read-only mode along with the content: on the second generation the
    // destination already exists without write permission and the copy fails
    // with "Permission denied", inside a build.rs.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
